    @Test
    @Timeout(value = 15, unit = TimeUnit.SECONDS)
    void testAsyncPaginationPaged() {
        SDK s = SDK.builder().serverURL(HTTPBIN_URL).build();
        // Test multi-page pagination with explicit limit parameter
        Publisher<PaginationLimitOffsetPageBodyResponse> publisher = s.async().pagination()
                .paginationLimitOffsetPageBody()
                .request(LimitOffsetConfig.builder()
                        .page(1L)
                        .limit(5L) // Set limit to demonstrate multi-page pagination
                        .build())
                .callAsPublisher();

        // Convert Flow.Publisher to List using Project Reactor
        CompletableFuture<List<PaginationLimitOffsetPageBodyResponse>> future =
                Flux.from(publisher)
                        .take(3) // Take the first 3 pages to demonstrate multipage pagination
                        .collectList()
                        .toFuture();

        assertThat(future).succeedsWithin(10, TimeUnit.SECONDS);
        List<PaginationLimitOffsetPageBodyResponse> responses = future.join();

        assertThat(responses)
                .isNotNull()
                .isNotEmpty();

        // Verify the first page has results and respects limit
        PaginationLimitOffsetPageBodyResponse firstPage = responses.get(0);
        assertThat(firstPage.statusCode()).isEqualTo(200);
        assertThat(firstPage.res())
                .isPresent()
                .hasValueSatisfying(pageRes ->
                        assertThat(pageRes.resultArray())
                                .isNotEmpty()
                                .hasSizeLessThanOrEqualTo(5)
                                .containsSubsequence(0L, 1L, 2L, 3L, 4L));

        // Verify we got multiple pages
        assertThat(responses).as("Should have multiple pages for multi-page pagination test")
                .hasSizeGreaterThan(1);
    }

