    @Test
    @Timeout(value = 15, unit = TimeUnit.SECONDS)
    void testAsyncPaginationCursor() {
        SDK s = SDK.builder().serverURL(HTTPBIN_URL).build();
        // Test cursor-based pagination with a numeric cursor
        Publisher<PaginationCursorParamsResponse> publisher =
                s.async().pagination()
                        .paginationCursorParams()
                        .cursor(1)
                        .callAsPublisher();

        // Use StepVerifier to test the reactive stream
        Flux<PaginationCursorParamsResponse> flux =
                Flux.from(publisher);

        StepVerifier.create(flux.take(3))
                .expectNextMatches(response -> {
                    assertThat(response)
                            .extracting(PaginationCursorParamsResponse::statusCode)
                            .isEqualTo(200);
                    assertThat(response.res())
                            .isPresent()
                            .hasValueSatisfying(pageRes -> {
                                assertThat(pageRes.resultArray())
                                        .isNotEmpty()
                                        .allSatisfy(item -> {
                                            // Cursor-based pagination returns sequential numbers from cursor
                                            assertThat(item).isGreaterThanOrEqualTo(0L);
                                        });
                                // Verify we get consecutive numbers starting from cursor value
                                if (pageRes.resultArray().size() >= 2) {
                                    assertThat(pageRes.resultArray().get(1))
                                            .isEqualTo(pageRes.resultArray().get(0) + 1);
                                }
                                // First item should match or be related to cursor value (1)
                                if (!pageRes.resultArray().isEmpty()) {
                                    assertThat(pageRes.resultArray().get(0)).isGreaterThanOrEqualTo(0L);
                                }
                            });
                    return true;
                })
                .expectNextCount(2) // Expect 2 more pages
                .verifyComplete();
    }

