    @Test
    @Timeout(value = 20, unit = TimeUnit.SECONDS)
    void testConcurrentPaginationPublishers() throws Exception {
        SDK s = SDK.builder().serverURL(HTTPBIN_URL).build();

        // Create publishers with different offsets
        List<Flux<Long>> fluxes = List.of(
                Flux.from(s.async().pagination().paginationLimitOffsetOffsetParams()
                        .offset(0L)
                        .callAsPublisherUnwrapped())
                        // consume only 10 items to avoid overlap with the next call
                        .take(10)
                ,
                Flux.from(s.async().pagination().paginationLimitOffsetOffsetParams()
                        .offset(10L)
                        .callAsPublisherUnwrapped())
        );

        // Merge all fluxes and group by even/odd
        Mono<Map<String, List<Long>>> grouped = Flux.merge(fluxes)
                .groupBy(n -> n % 2 == 0 ? "even" : "odd")
                .flatMap(group -> group.collectList()
                        .map(list -> Map.entry(group.key(), list)))
                .collectMap(Map.Entry::getKey, Map.Entry::getValue);

        StepVerifier.create(grouped)
                .expectNextMatches(groupedResults -> {
                    assertThat(groupedResults)
                            .containsKeys("even", "odd");

                    List<Long> evenNumbers = groupedResults.get("even");
                    List<Long> oddNumbers = groupedResults.get("odd");

                    // Verify both even and odd groups have numbers
                    assertThat(evenNumbers)
                            .as("Should have 10 even numbers")
                            .hasSize(10)
                            .allSatisfy(n -> assertThat(n % 2).isEqualTo(0));

                    assertThat(oddNumbers)
                            .as("Should have 10 odd numbers")
                            .hasSize(10)
                            .allSatisfy(n -> assertThat(n % 2).isEqualTo(1));

                    return true;
                })
                .verifyComplete();
    }

    @Test
    @Timeout(value = 15, unit = TimeUnit.SECONDS)
    void testAsyncMultiPagePaginationWithVariousLimits() throws Exception {
        SDK s = SDK.builder().serverURL(HTTPBIN_URL).build();
        // Test pagination with different limit values to demonstrate multipage behavior
        int[] limits = {2, 5, 10};

        for (int limit : limits) {
            Publisher<PaginationLimitOffsetOffsetParamsResponse> publisher = s.async().pagination()
                    .paginationLimitOffsetOffsetParams()
                    .offset(0L)
                    .limit((long) limit)
                    .callAsPublisher();

            // Use StepVerifier to test the reactive stream
            Flux<PaginationLimitOffsetOffsetParamsResponse> flux =
                    Flux.from(publisher);

            StepVerifier.create(flux.take(2)) // Take 2 pages for each limit
                    .expectNextMatches(response -> {
                        assertThat(response.statusCode()).isEqualTo(200);
                        assertThat(response.res())
                                .isPresent()
                                .hasValueSatisfying(pageRes -> {
                                    assertThat(pageRes.resultArray())
                                            .isNotEmpty()
                                            .hasSizeLessThanOrEqualTo(limit);
                                    if (!pageRes.resultArray().isEmpty()) {
                                        assertThat(pageRes.resultArray().get(0)).isEqualTo(0L);
                                    }
                                });
                        return true;
                    })
                    .expectNextCount(1) // Expect 1 more page
                    .verifyComplete();
        }
    }

