    @Test
    @Timeout(value = 20, unit = TimeUnit.SECONDS)
    void testAsyncPaginationSlowConsumer() throws Exception {
        SDK s = SDK.builder().serverURL(HTTPBIN_URL).build();
        // Test slow consumer scenario: Verify backpressure handling
        Publisher<PaginationLimitOffsetOffsetParamsResponse> publisher = s.async().pagination()
                .paginationLimitOffsetOffsetParams()
                .offset(0L)
                .limit(3L)
                .callAsPublisher();

        // Use StepVerifier with slow consumer simulation
        Flux<PaginationLimitOffsetOffsetParamsResponse> flux =
                Flux.from(publisher);

        StepVerifier.create(flux.take(2))
                .expectNextMatches(response -> {
                    assertThat(response.statusCode()).isEqualTo(200);
                    assertThat(response.res())
                            .isPresent()
                            .hasValueSatisfying(pageRes -> {
                                assertThat(pageRes.resultArray()).isNotEmpty();
                                if (!pageRes.resultArray().isEmpty()) {
                                    assertThat(pageRes.resultArray().get(0)).isEqualTo(0L);
                                }
                            });
                    // Simulate slow processing
                    try {
                        Thread.sleep(500);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                    return true;
                })
                .expectNextMatches(response -> {
                    assertThat(response)
                            .extracting(PaginationLimitOffsetOffsetParamsResponse::statusCode)
                            .isEqualTo(200);
                    assertThat(response.res()).isPresent();
                    // Simulate slow processing again
                    try {
                        Thread.sleep(500);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                    return true;
                })
                .verifyComplete();
    }

